#!/usr/bin/env node
// Regenerates src/guides.generated.ts from the public guide page, so `get_guide` serves the words
// the page shows and nothing else. `--check` compares instead of writing; the test beside the
// generated file asserts the same equality, so a page edit without a regeneration fails twice.
//
//   npm run sync:guides          (builds first: the splitter is shared with the package)
//   npm run check:guides
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { splitGuides } from "../dist/guides-split.js";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PAGE = resolve(ROOT, "../../../docs/learn/using-ai-with-bitbybit/agentic-cad.md");
const OUTPUT = resolve(ROOT, "src/guides.generated.ts");
const URL = "https://learn.bitbybit.dev/learn/using-ai-with-bitbybit/agentic-cad";

export function renderGuides(markdown) {
    const sections = splitGuides(markdown);
    return [
        "import type { GuideSection } from \"./guides-split.js\";",
        "",
        "/** Where the guide is published; every section links back to it. */",
        `export const GUIDE_PAGE_URL = ${JSON.stringify(URL)};`,
        "",
        "/**",
        " * The sections of the public guide, generated by scripts/sync-guides.mjs from",
        " * docs/learn/using-ai-with-bitbybit/agentic-cad.md. Do not edit: run `npm run sync:guides`.",
        " */",
        `export const GUIDES: readonly GuideSection[] = ${JSON.stringify(sections, null, 4)};`,
        "",
    ].join("\n");
}

const check = process.argv.includes("--check");
const rendered = renderGuides(readFileSync(PAGE, "utf8"));
const current = readFileSync(OUTPUT, "utf8");
if (check) {
    if (rendered !== current) {
        console.error("src/guides.generated.ts is not what the guide page produces - run `npm run sync:guides` and commit the result");
        process.exit(1);
    }
    console.log("src/guides.generated.ts matches the guide page");
} else if (rendered === current) {
    console.log("src/guides.generated.ts is already current");
} else {
    writeFileSync(OUTPUT, rendered);
    console.log(`wrote src/guides.generated.ts (${splitGuides(readFileSync(PAGE, "utf8")).length} sections)`);
}
